def pointIndex (x : ℝ) (hx : x ∈ Ioc (0 : ℝ) 1) (j : ℕ) : Fin (2 ^ (0 + j)) :=
  Classical.choose (show ∃ k : Fin (2 ^ (0 + j)), x ∈ lpHaarCell (0 + j) k from
    mem_iUnion.mp (by rw [lpHaarLevelCells_union]; exact hx))

